import React from "react";

const Pagination = ({ filter, totalItems, onPageChange }) => {
    const totalPages = Math.max(1, Math.ceil(totalItems / filter.limit)); // Zajišťuje alespoň 1 stránku

    if (totalPages === 1) return null; // Skryje stránkování, pokud není potřeba

    return (
        <nav>
            <ul className="pagination justify-content-center mt-3">
                <li className={`page-item ${filter.page === 0 ? "disabled" : ""}`}>
                    <button
                        className="page-link"
                        onClick={() => onPageChange(filter.page - 1)}
                        disabled={filter.page === 0}
                    >
                        Předchozí
                    </button>
                </li>

                {Array.from({ length: totalPages }, (_, index) => (
                    <li key={index} className={`page-item ${filter.page === index ? "active" : ""}`}>
                        <button className="page-link" onClick={() => onPageChange(index)}>
                            {index + 1}
                        </button>
                    </li>
                ))}

                <li className={`page-item ${filter.page >= totalPages - 1 ? "disabled" : ""}`}>
                    <button
                        className="page-link"
                        onClick={() => onPageChange(filter.page + 1)}
                        disabled={filter.page >= totalPages - 1}
                    >
                        Další
                    </button>
                </li>
            </ul>
        </nav>
    );
};

export default Pagination;
